INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('kolac-od-niky', 'cs', 'Koláč od Niky', 'Rodinná receptura: jemná cuketa, poctivý bramborový základ, táhnoucí se mozzarella, čerstvý špenát a česnek. Bez smetany, a stejně vláčný.', '[{"text": "Troubu předehřej na 180 °C. Smíchej sůl, pepř a majoránku.", "obrazek": "kolac-koreni.webp"}, {"text": "Brambory nakrájej na tenké plátky a vyskládej jimi dno formy.", "obrazek": "kolac-krok-2.webp"}, {"text": "Na brambory rozlož mleté maso promíchané s česnekem a polovinou kořenící směsi.", "obrazek": "kolac-krok-3.webp"}, {"text": "Cuketu nastrouhej, lehce vymačkej a rozprostři na maso.", "obrazek": "kolac-krok-4.webp"}, {"text": "Přidej špenát a natrhanou mozzarellu.", "obrazek": "kolac-krok-5.webp"}, {"text": "Vejce rozšlehej se zbytkem koření, zalij jimi koláč a posyp piniovými oříšky.", "obrazek": "kolac-krok-6.webp"}, {"text": "Peč asi 45 minut, dokud vejce neztuhnou a povrch nezezlátne."}]', NULL, 'Koláč vydrží v lednici 3 dny, takže je skvělý na vaření dopředu. Piniové oříšky nepatří mezi 14 hlavních alergenů EU, ale při alergii na ořechy buď opatrná.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('kolac-od-niky', 'en', 'Niky''s Pie', 'A family recipe: tender courgette, a hearty potato base, stretchy mozzarella, fresh spinach and garlic. No cream, and still moist.', '[{"text": "Preheat the oven to 180 °C. Mix salt, pepper and marjoram.", "obrazek": "kolac-koreni.webp"}, {"text": "Slice the potatoes thinly and line the bottom of the dish.", "obrazek": "kolac-krok-2.webp"}, {"text": "Spread the mince, mixed with garlic and half of the seasoning, over the potatoes.", "obrazek": "kolac-krok-3.webp"}, {"text": "Grate the courgette, squeeze it lightly and spread it over the meat.", "obrazek": "kolac-krok-4.webp"}, {"text": "Add the spinach and torn mozzarella.", "obrazek": "kolac-krok-5.webp"}, {"text": "Whisk the eggs with the rest of the seasoning, pour over and sprinkle with pine nuts.", "obrazek": "kolac-krok-6.webp"}, {"text": "Bake for about 45 minutes until the eggs set and the top turns golden."}]', NULL, 'Keeps in the fridge for 3 days, perfect for cooking ahead. Pine nuts are not one of the 14 main EU allergens, but take care if you have a nut allergy.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('pecena-zelenina-s-quinoou', 'cs', 'Pečená zelenina s quinoou – základ na 3 dny', 'Jeden plech, tři různé večeře. V neděli upeč základ a každý den ho dochuť jinak.', '[{"text": "Troubu předehřej na 200 °C. Zeleninu nakrájej na kousky, promíchej s olejem a kořením."}, {"text": "Peč na plechu asi 25 minut, v polovině promíchej."}, {"text": "Mezitím uvař quinou podle návodu na obalu."}, {"text": "Smíchej zeleninu s quinoou a rozděl do 3 krabiček. V lednici vydrží 3 dny."}]', '[{"text": "Přidej grilované kuřecí maso. Víc bílkovin, hodí se při nabírání.", "nazev": "A – sytá"}, {"text": "Přidej cizrnu a lžíci tahini. Bez masa. Pozor: tahini obsahuje sezam.", "nazev": "B – rostlinná"}, {"text": "Přidej fetu a vejce natvrdo. Hotové za 5 minut. Obsahuje mléko a vejce.", "nazev": "C – rychlá"}]', NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('pecena-zelenina-s-quinoou', 'en', 'Roasted vegetables with quinoa – a 3-day base', 'One tray, three different dinners. Roast the base on Sunday and give it a new twist every day.', '[{"text": "Preheat the oven to 200 °C. Chop the vegetables and toss with oil and spices."}, {"text": "Roast for about 25 minutes, stirring halfway."}, {"text": "Meanwhile cook the quinoa according to the packet."}, {"text": "Mix vegetables with quinoa and divide into 3 boxes. Keeps for 3 days in the fridge."}]', '[{"text": "Add grilled chicken. More protein, good for building muscle.", "nazev": "A – hearty"}, {"text": "Add chickpeas and a spoon of tahini. No meat. Note: tahini contains sesame.", "nazev": "B – plant-based"}, {"text": "Add feta and a hard-boiled egg. Ready in 5 minutes. Contains milk and egg.", "nazev": "C – quick"}]', NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('kureci-salat-s-quinoou', 'cs', 'Kuřecí salát s quinoou', 'Sytý salát do krabičky, který tě podrží celé odpoledne.', '[{"text": "Quinou uvař a nech vychladnout."}, {"text": "Kuřecí prsa osol, opepři a opeč na pánvi dozlatova, pak nakrájej."}, {"text": "Rajčata a okurku nakrájej na kostičky."}, {"text": "Vše smíchej s olejem, citronem a petrželkou."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('kureci-salat-s-quinoou', 'en', 'Chicken salad with quinoa', 'A filling lunchbox salad that keeps you going all afternoon.', '[{"text": "Cook the quinoa and let it cool."}, {"text": "Season the chicken and pan-fry until golden, then slice."}, {"text": "Dice the tomatoes and cucumber."}, {"text": "Mix everything with oil, lemon juice and parsley."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('cockovy-salat-s-fetou', 'cs', 'Čočkový salát s fetou', 'Levný, rychlý a plný vlákniny. Druhý den chutná ještě líp.', '[{"text": "Čočku uvař doměkka (asi 20 minut) a sceď."}, {"text": "Cibuli nakrájej najemno, rajčata na kostičky."}, {"text": "Smíchej s čočkou, olejem a citronem, navrch rozdrob fetu."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('cockovy-salat-s-fetou', 'en', 'Lentil salad with feta', 'Cheap, quick and full of fibre. Tastes even better the next day.', '[{"text": "Cook the lentils until soft (about 20 minutes) and drain."}, {"text": "Finely chop the onion, dice the tomatoes."}, {"text": "Mix with lentils, oil and lemon, crumble feta on top."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('omeleta-se-zeleninou', 'cs', 'Omeleta se zeleninou a sýrem', 'Záchranná večeře za 15 minut z toho, co máš v lednici.', '[{"text": "Zeleninu nakrájej a krátce opeč na oleji."}, {"text": "Vejce rozšlehej se solí a pepřem a zalij jimi zeleninu."}, {"text": "Posyp sýrem, přiklop a nech 3 minuty dojít na mírném ohni."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('omeleta-se-zeleninou', 'en', 'Vegetable and cheese omelette', 'A rescue dinner in 15 minutes from whatever is in your fridge.', '[{"text": "Chop the vegetables and fry briefly in oil."}, {"text": "Whisk the eggs with salt and pepper and pour over."}, {"text": "Sprinkle with cheese, cover and cook gently for 3 minutes."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('tvarohova-pomazanka', 'cs', 'Tvarohová pomazánka na kváskovém chlebu', 'Snídaně nebo lehká večeře plná bílkovin, hotová za 10 minut.', '[{"text": "Tvaroh rozmíchej s jogurtem, solí a pepřem."}, {"text": "Přidej nasekanou pažitku a nakrájené ředkvičky."}, {"text": "Namaž na chléb."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('tvarohova-pomazanka', 'en', 'Quark spread on sourdough bread', 'A protein-rich breakfast or light dinner, ready in 10 minutes.', '[{"text": "Mix the quark with yoghurt, salt and pepper."}, {"text": "Add chopped chives and sliced radishes."}, {"text": "Spread on the bread."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('ovesna-kase-s-jablkem', 'cs', 'Ovesná kaše s jablkem a skořicí', 'Teplá snídaně, která zasytí do oběda.', '[{"text": "Vločky vař v mléce asi 5 minut za stálého míchání."}, {"text": "Jablko nastrouhej nebo nakrájej a přimíchej se skořicí."}, {"text": "Posyp ořechy, podle chuti přidej med."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('ovesna-kase-s-jablkem', 'en', 'Porridge with apple and cinnamon', 'A warm breakfast that keeps you full until lunch.', '[{"text": "Simmer the oats in milk for about 5 minutes, stirring."}, {"text": "Grate or chop the apple and stir in with cinnamon."}, {"text": "Top with walnuts and add honey to taste."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('bananovy-chlebicek', 'cs', 'Banánový chlebíček bez přidaného cukru', 'Sladkost dodají zralé banány. Ideální sladká tečka ke kávě.', '[{"text": "Troubu předehřej na 180 °C a formu vyskládej papírem."}, {"text": "Banány rozmačkej, přidej vejce a promíchej."}, {"text": "Vmíchej vločky, prášek do pečiva, skořici a ořechy."}, {"text": "Peč asi 40 minut, nech vychladnout a nakrájej na 10 plátků."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('bananovy-chlebicek', 'en', 'Banana bread with no added sugar', 'Ripe bananas bring the sweetness. A perfect sweet treat with coffee.', '[{"text": "Preheat the oven to 180 °C and line a loaf tin."}, {"text": "Mash the bananas, add the eggs and mix."}, {"text": "Stir in oats, baking powder, cinnamon and walnuts."}, {"text": "Bake for about 40 minutes, cool and cut into 10 slices."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('tvarohovy-dezert-s-jahodami', 'cs', 'Tvarohový dezert s jahodami', 'Sladká tečka plná bílkovin, hotová za 10 minut.', '[{"text": "Tvaroh vyšlehej s jogurtem, medem a vanilkou."}, {"text": "Jahody nakrájej."}, {"text": "Vrstvi do skleniček krém a jahody."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('tvarohovy-dezert-s-jahodami', 'en', 'Quark dessert with strawberries', 'A protein-rich sweet treat, ready in 10 minutes.', '[{"text": "Whip the quark with yoghurt, honey and vanilla."}, {"text": "Slice the strawberries."}, {"text": "Layer cream and strawberries in glasses."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('datlove-kulicky', 'cs', 'Čokoládové kuličky z datlí', 'Tři kuličky jako sladká tečka po obědě. Bez pečení.', '[{"text": "Ořechy rozmixuj najemno."}, {"text": "Přidej datle, kakao a sůl a mixuj, dokud se hmota nespojí."}, {"text": "Tvaruj 12 kuliček a obal v kokosu. Uchovej v lednici."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('datlove-kulicky', 'en', 'Chocolate date balls', 'Three balls as a sweet treat after lunch. No baking.', '[{"text": "Blend the nuts finely."}, {"text": "Add dates, cocoa and salt and blend until it sticks together."}, {"text": "Roll 12 balls and coat in coconut. Keep in the fridge."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('jogurtovy-ovocny-pohar', 'cs', 'Jogurtový ovocný pohár', 'Vrstvy jogurtu, ovoce a křupavých vloček. Vypadá jako z cukrárny.', '[{"text": "Vločky opraž nasucho na pánvi dozlatova."}, {"text": "Jogurt promíchej s medem, kiwi nakrájej."}, {"text": "Vrstvi do pohárů jogurt, ovoce a vločky, ozdob mátou."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('jogurtovy-ovocny-pohar', 'en', 'Yoghurt fruit parfait', 'Layers of yoghurt, fruit and crunchy oats. Looks like it came from a patisserie.', '[{"text": "Toast the oats in a dry pan until golden."}, {"text": "Stir honey into the yoghurt, slice the kiwi."}, {"text": "Layer yoghurt, fruit and oats in glasses, garnish with mint."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('ledova-kava-s-vanilkou', 'cs', 'Domácí ledová káva s vanilkou', 'Osvěžující kávový drink s kapkou vanilky a rostlinným mlékem pro horké dny.', '[{"text": "Uvař kávu a nech ji vychladnout."}, {"text": "Do vysoké sklenice nasyp led a zalij ho mlékem s kapkou vanilky."}, {"text": "Opatrně přilij kávu, vznikne mramorový efekt. Před pitím promíchej."}]', NULL, 'Mandlové mléko obsahuje ořechy, ovesné může obsahovat lepek. Vyber podle sebe.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('ledova-kava-s-vanilkou', 'en', 'Homemade iced coffee with vanilla', 'A refreshing coffee drink with a drop of vanilla and plant milk for hot days.', '[{"text": "Brew the coffee and let it cool."}, {"text": "Fill a tall glass with ice and pour in the milk with a drop of vanilla."}, {"text": "Gently pour in the coffee for a marbled look. Stir before drinking."}]', NULL, 'Almond milk contains nuts, oat milk may contain gluten. Choose what suits you.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('okurkova-limonada', 'cs', 'Okurková limonáda s limetkou a mátou', 'Svěží domácí limonáda z čerstvé okurky, limetky a máty.', '[{"text": "Okurku rozmixuj s trochou vody na hladké pyré."}, {"text": "Pyré sceď přes jemné sítko."}, {"text": "Smíchej s limetkovou šťávou, medem a podrcenou mátou."}, {"text": "Zalij perlivou vodou, přidej led a plátky okurky."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('okurkova-limonada', 'en', 'Cucumber lemonade with lime and mint', 'A fresh homemade lemonade with cucumber, lime and mint.', '[{"text": "Blend the cucumber with a little water until smooth."}, {"text": "Strain through a fine sieve."}, {"text": "Mix with lime juice, honey and crushed mint."}, {"text": "Top with sparkling water, add ice and cucumber slices."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('ginger-shot', 'cs', 'Domácí ginger shot', 'Malá sklenička, která tě ráno probudí. Doma ho máš za pár minut a bez zbytečného cukru.', '[{"text": "Zázvor omyj a nakrájej na kousky (loupat nemusíš)."}, {"text": "Rozmixuj s vodou a citronovou šťávou."}, {"text": "Sceď, vmíchej med a rozlij do 4 malých skleniček. V lednici vydrží 3 dny."}]', NULL, 'Je pořádně ostrý. Začni s polovinou panáku.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('ginger-shot', 'en', 'Homemade ginger shot', 'A tiny glass that wakes you up in the morning. Made at home in minutes, with no unnecessary sugar.', '[{"text": "Wash the ginger and cut into pieces (no need to peel)."}, {"text": "Blend with water and lemon juice."}, {"text": "Strain, stir in honey and pour into 4 small glasses. Keeps for 3 days in the fridge."}]', NULL, 'It is really spicy. Start with half a shot.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('zelene-smoothie', 'cs', 'Zelené smoothie', 'Rychlá snídaně do ruky. Špenát nebude cítit, slibuju.', '[{"text": "Vše dej do mixéru."}, {"text": "Mixuj do hladka, podle potřeby přidej vodu."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('zelene-smoothie', 'en', 'Green smoothie', 'A quick breakfast on the go. You won''t taste the spinach, promise.', '[{"text": "Put everything in a blender."}, {"text": "Blend until smooth, adding water as needed."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('ledovy-caj-s-matou', 'cs', 'Ledový čaj s mátou a citronem', 'Domácí ledový čaj bez kupovaného sirupu. Sladkost si určíš sama.', '[{"text": "Čaj zalij horkou vodou a nech 4 minuty louhovat."}, {"text": "Vyndej sáčky, vmíchej med a nech vychladnout."}, {"text": "Přidej citron, mátu a led."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('ledovy-caj-s-matou', 'en', 'Iced tea with mint and lemon', 'Homemade iced tea without bought syrup. You decide how sweet it is.', '[{"text": "Pour hot water over the tea and steep for 4 minutes."}, {"text": "Remove the bags, stir in honey and let it cool."}, {"text": "Add lemon, mint and ice."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('latte-s-ovesnym-mlekem', 'cs', 'Latte s ovesným mlékem', 'Kavárenské latte doma za 5 minut.', '[{"text": "Připrav espresso."}, {"text": "Mléko ohřej a napěň (stačí uzavřená sklenice a pořádné protřepání)."}, {"text": "Nalij mléko do kávy a posyp skořicí."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('latte-s-ovesnym-mlekem', 'en', 'Oat milk latte', 'A café-style latte at home in 5 minutes.', '[{"text": "Make the espresso."}, {"text": "Warm and froth the milk (a closed jar and a good shake will do)."}, {"text": "Pour the milk into the coffee and sprinkle with cinnamon."}]', NULL, NULL, NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('tvarohove-livance', 'cs', 'Tvarohové lívance s borůvkami', 'Nedělní snídaně, která zasytí do oběda. Hodně bílkovin, málo práce.', '[{"text": "Rozmixuj nebo rozmačkej tvaroh s vejci a ovesnými vločkami."}, {"text": "Vmíchej prášek do pečiva a nech těsto 5 minut odpočinout."}, {"text": "Na pánvi s troškou oleje peč malé lívance z obou stran dozlatova."}, {"text": "Podávej s borůvkami."}]', NULL, 'Těsto vydrží do druhého dne v lednici – ráno jen upečeš.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('tvarohove-livance', 'en', 'Quark pancakes with blueberries', 'A Sunday breakfast that keeps you full until lunch. Lots of protein, little effort.', '[{"text": "Blend or mash the quark with the eggs and oats."}, {"text": "Stir in the baking powder and let the batter rest for 5 minutes."}, {"text": "Fry small pancakes in a little oil until golden on both sides."}, {"text": "Serve with blueberries."}]', NULL, 'The batter keeps in the fridge until the next day – just fry it in the morning.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('chilli-sin-carne', 'cs', 'Chilli sin carne s fazolemi', 'Chilli bez masa, které nikomu nechybí. Uvaříš jednou a máš na tři dny.', '[{"text": "Na oleji osmahni nakrájenou cibuli, česnek a papriku."}, {"text": "Přidej koření, krátce orestuj a zalij rajčaty."}, {"text": "Vmíchej scezené fazole a kukuřici a duš 20 minut."}, {"text": "Mezitím uvař rýži a podávej spolu."}]', NULL, 'Druhý den chutná ještě líp. Ostrost si řiď množstvím chilli.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('chilli-sin-carne', 'en', 'Bean chilli sin carne', 'A meat-free chilli nobody misses the meat in. Cook once, eat for three days.', '[{"text": "Fry the chopped onion, garlic and pepper in the oil."}, {"text": "Add the spices, fry briefly and pour in the tomatoes."}, {"text": "Stir in the drained beans and sweetcorn and simmer for 20 minutes."}, {"text": "Cook the rice in the meantime and serve together."}]', NULL, 'It tastes even better the next day. Adjust the heat with the amount of chilli.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('losos-s-bramborem', 'cs', 'Pečený losos s bramborem a brokolicí', 'Jeden plech, žádné nádobí navíc. Večeře, která vypadá jako z restaurace.', '[{"text": "Brambory nakrájej na kostky, promíchej s polovinou oleje a peč 15 minut na 200 °C."}, {"text": "Přidej růžičky brokolice a lososa, pokapej zbytkem oleje a citronem."}, {"text": "Peč dalších 12–15 minut, až se losos snadno rozdělí vidličkou."}, {"text": "Posyp koprem a podávej."}]', NULL, 'Místo lososa jde i pstruh nebo treska.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('losos-s-bramborem', 'en', 'Baked salmon with potatoes and broccoli', 'One tray, no extra washing up. A dinner that looks restaurant-made.', '[{"text": "Cube the potatoes, toss with half the oil and roast for 15 minutes at 200 °C."}, {"text": "Add the broccoli florets and salmon, drizzle with the rest of the oil and lemon."}, {"text": "Roast for another 12–15 minutes until the salmon flakes easily."}, {"text": "Sprinkle with dill and serve."}]', NULL, 'Trout or cod work instead of salmon too.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('kureci-wrap', 'cs', 'Kuřecí wrap s jogurtovým dresinkem', 'Oběd do krabičky, který se nerozpadne. Hotový za 20 minut.', '[{"text": "Kuřecí prsa nakrájej na nudličky, osol, opepři a opeč na oleji."}, {"text": "Jogurt smíchej se solí, pepřem a trochou citronu."}, {"text": "Tortillu potři dresinkem, poskládej salát, zeleninu a maso."}, {"text": "Pevně zabal a rozkroj napůl."}]', NULL, 'Do krabičky zabal wrap do pečicího papíru – drží tvar.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('kureci-wrap', 'en', 'Chicken wrap with yoghurt dressing', 'A lunchbox meal that holds together. Ready in 20 minutes.', '[{"text": "Slice the chicken into strips, season and fry in the oil."}, {"text": "Mix the yoghurt with salt, pepper and a little lemon."}, {"text": "Spread the dressing on the tortilla, add lettuce, vegetables and chicken."}, {"text": "Roll it up tightly and cut in half."}]', NULL, 'Wrap it in baking paper for your lunchbox – it keeps its shape.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('hummus-se-zeleninou', 'cs', 'Hummus se zeleninou na namáčení', 'Svačina, která vydrží v lednici celý týden. Hlad v pět odpoledne vyřešen.', '[{"text": "Cizrnu sceď, část vody z plechovky si nech."}, {"text": "Rozmixuj cizrnu s tahini, citronem, česnekem, olejem a solí. Podle potřeby přilij vodu z cizrny."}, {"text": "Zeleninu nakrájej na hranolky a namáčej."}]', NULL, 'Hummus vydrží v uzavřené krabičce 5 dní.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('hummus-se-zeleninou', 'en', 'Hummus with vegetable dippers', 'A snack that lasts all week in the fridge. Five-o-clock hunger, sorted.', '[{"text": "Drain the chickpeas, keeping some of the liquid."}, {"text": "Blend the chickpeas with tahini, lemon, garlic, oil and salt. Add some chickpea liquid if needed."}, {"text": "Cut the vegetables into sticks and dip."}]', NULL, 'Hummus keeps for 5 days in a closed container.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('shakshuka', 'cs', 'Shakshuka – vejce v rajčatové omáčce', 'Jedna pánev, vajíčka a voňavá omáčka. K snídani i k večeři.', '[{"text": "Na oleji osmahni cibuli, papriku a česnek, přidej kmín a papriku."}, {"text": "Zalij rajčaty a 5 minut povař, ať omáčka zhoustne."}, {"text": "Udělej 4 důlky, rozklepni do nich vejce, přiklop a nech 6–8 minut, až bílek ztuhne."}, {"text": "Posyp fetou a podávej s chlebem."}]', NULL, 'Kdo nemá rád tekutý žloutek, nechá pod pokličkou o 2 minuty déle.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('shakshuka', 'en', 'Shakshuka – eggs in tomato sauce', 'One pan, eggs and a fragrant sauce. Good for breakfast or dinner.', '[{"text": "Fry the onion, pepper and garlic in the oil, add cumin and paprika."}, {"text": "Pour in the tomatoes and simmer for 5 minutes until the sauce thickens."}, {"text": "Make 4 wells, crack in the eggs, cover and cook for 6–8 minutes until the whites set."}, {"text": "Sprinkle with feta and serve with bread."}]', NULL, 'Not a fan of runny yolks? Leave the lid on for 2 more minutes.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('chia-puding-s-malinami', 'cs', 'Chia puding s malinami', 'Večer pět minut, ráno hotová snídaně. Stačí lžička a sklenička.', '[{"text": "Smíchej chia semínka s mlékem, jogurtem a medem."}, {"text": "Po 10 minutách ještě jednou promíchej, ať nejsou hrudky."}, {"text": "Nech přes noc v lednici a ráno ozdob malinami."}]', NULL, 'Udělej rovnou dvě skleničky – jedna je na zítra.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('chia-puding-s-malinami', 'en', 'Chia pudding with raspberries', 'Five minutes in the evening, breakfast ready in the morning.', '[{"text": "Mix the chia seeds with milk, yoghurt and honey."}, {"text": "Stir again after 10 minutes so there are no lumps."}, {"text": "Leave in the fridge overnight and top with raspberries in the morning."}]', NULL, 'Make two jars at once – one is for tomorrow.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('cizrnove-kari', 'cs', 'Cizrnové kari se špenátem', 'Hřejivé kari bez masa, sytá porce na chladné dny. Vaří se samo.', '[{"text": "Na oleji osmahni cibuli, česnek a nastrouhaný zázvor."}, {"text": "Přidej kari koření, krátce orestuj a zalij rajčaty a kokosovým mlékem."}, {"text": "Vmíchej scezenou cizrnu a duš 15 minut."}, {"text": "Nakonec vmíchej špenát, nech zavadnout a podávej s rýží."}]', NULL, 'Na lehčí verzi použij light kokosové mléko a menší porci rýže.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('cizrnove-kari', 'en', 'Chickpea curry with spinach', 'A warming meat-free curry, a filling bowl for cold days. It cooks itself.', '[{"text": "Fry the onion, garlic and grated ginger in the oil."}, {"text": "Add the curry powder, fry briefly and pour in the tomatoes and coconut milk."}, {"text": "Stir in the drained chickpeas and simmer for 15 minutes."}, {"text": "Finally stir in the spinach, let it wilt and serve with rice."}]', NULL, 'For a lighter version use light coconut milk and less rice.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('bananovy-shake-s-tvarohem', 'cs', 'Banánový shake s tvarohem a arašídovým máslem', 'Snídaně do ruky nebo svačina po tréninku. Sytá a bez proteinového prášku.', '[{"text": "Všechno dej do mixéru."}, {"text": "Mixuj do hladka, asi 30 sekund."}, {"text": "Nalij do sklenice a posyp skořicí."}]', NULL, 'S mraženým banánem je shake hustý a studený jako zmrzlina.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('bananovy-shake-s-tvarohem', 'en', 'Banana shake with quark and peanut butter', 'Breakfast on the go or a post-workout snack. Filling, no protein powder needed.', '[{"text": "Put everything in a blender."}, {"text": "Blend until smooth, about 30 seconds."}, {"text": "Pour into a glass and sprinkle with cinnamon."}]', NULL, 'With a frozen banana the shake gets thick and cold like ice cream.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('pohankova-kase-s-jablkem', 'cs', 'Pohanková kaše s jablkem a skořicí', 'Teplá snídaně bez mléka a bez lepku. Voní jako jablečný koláč.', '[{"text": "Pohanku propláchni a vař ve vodě se špetkou soli asi 10 minut doměkka."}, {"text": "Nastrouhej do ní jablko, přidej skořici a krátce povař."}, {"text": "Osladí sirup, navrch nasyp dýňová semínka."}]', NULL, 'Pohanka je přirozeně bez lepku. Uvař jí víc – v lednici vydrží 3 dny.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('pohankova-kase-s-jablkem', 'en', 'Buckwheat porridge with apple and cinnamon', 'A warm breakfast without milk or gluten. It smells like apple pie.', '[{"text": "Rinse the buckwheat and simmer it in water with a pinch of salt for about 10 minutes until soft."}, {"text": "Grate in the apple, add cinnamon and cook briefly."}, {"text": "Sweeten with syrup and top with pumpkin seeds."}]', NULL, 'Buckwheat is naturally gluten-free. Cook extra – it keeps for 3 days in the fridge.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('tofu-michanice', 'cs', 'Tofu míchanice se zeleninou', 'Jako míchaná vajíčka, jen bez vajec a bez mléka. Plná bílkovin.', '[{"text": "Na oleji osmahni nakrájenou cibuli a papriku."}, {"text": "Tofu rozdrob rukama do pánve, přidej kurkumu, sůl a pepř a 5 minut opékej."}, {"text": "Přidej rajče a špenát, nech zavadnout."}, {"text": "Podávej s plátky avokáda."}]', NULL, 'Kurkuma dá tofu žlutou barvu jako u vajíček. Kdo má rád, přidá špetku černé soli kala namak – voní po vajíčkách.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('tofu-michanice', 'en', 'Tofu scramble with vegetables', 'Like scrambled eggs, just without eggs or milk. Packed with protein.', '[{"text": "Fry the chopped onion and pepper in the oil."}, {"text": "Crumble the tofu into the pan, add turmeric, salt and pepper and fry for 5 minutes."}, {"text": "Add the tomato and spinach and let it wilt."}, {"text": "Serve with sliced avocado."}]', NULL, 'Turmeric gives the tofu an egg-like colour. A pinch of kala namak (black salt) even makes it smell like eggs.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('bataty-s-vejcem', 'cs', 'Pečené batáty s vejcem a avokádem', 'Sytá snídaně na víkend nebo rychlý oběd. Bez mléka a bez lepku.', '[{"text": "Batát nakrájej na kostky, promíchej s olejem, solí a paprikou a peč 20 minut na 200 °C."}, {"text": "Mezitím uvař vejce nahniličko (6–7 minut) nebo je usmaž."}, {"text": "Batáty dej na talíř, přidej vejce a plátky avokáda, posyp semínky."}]', NULL, 'Batáty se dají upéct večer předem – ráno je jen ohřeješ.', NULL);
INSERT INTO public.recepty_texty (recept, jazyk, nazev, uvod, postup, varianty, tip, pribeh) VALUES ('bataty-s-vejcem', 'en', 'Roasted sweet potato with egg and avocado', 'A filling weekend breakfast or quick lunch. No milk, no gluten.', '[{"text": "Cube the sweet potato, toss with oil, salt and paprika and roast for 20 minutes at 200 °C."}, {"text": "Meanwhile soft-boil the eggs (6–7 minutes) or fry them."}, {"text": "Plate the sweet potato, add the eggs and sliced avocado and sprinkle with seeds."}]', NULL, 'You can roast the sweet potato the evening before – just warm it up in the morning.', NULL);
